55	const PROCESSING_FEE = 5;
56	
57	const FIRST_INSURANCE_SURCHARGE = 0.1;
58	
59	const BASE_PREMIUMS: Record<string, number> = {
60	  sword: 100,
61	  amulet: 60,
62	  staff: 80,
63	};
64	
65	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
66	
67	const policyBasePremium = (items: Item[]): number =>
68	  items.reduce((sum, item) => sum + itemBasePremium(item), 0);
69	
70	const quotePremium = (items: Item[]): number => {
71	  const policyBase = policyBasePremium(items);
72	  return policyBase + policyBase * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE;
73	};
74	
75	const runStep = (step: Step): StepResult => ({
76	  premium: quotePremium((step as QuoteStep).items),
77	});
78	
79	export const runScenario = (scenario: Scenario): ScenarioResult => ({
80	  results: scenario.steps.map(runStep),
81	});
